import AxoMascot
import RiveRuntime
import SwiftUI

/// One on-screen Axo: the `Face` artboard of `axo.riv` (generated by `packages/axo-mascot`) and
/// the inputs of its `Mascot` state machine. Looking around and blinking happen in the file; the
/// app only says where to look, when to cover the eyes and when it was poked.
@MainActor
final class Mascot: ObservableObject {
  /// Names in `packages/axo-mascot/src/mascot.ts` (`MascotContract`).
  private enum Input {
    static let poke = "poke"
    static let annoyed = "annoyed"
    static let tracking = "tracking"
    static let covering = "covering"
    static let lookX = "lookX"
    static let lookY = "lookY"
    static let loading = "loading"
  }

  enum Artboard {
    static let face = "Face"
    /// Square, with room to spin.
    static let loader = "Loader"
  }

  /// Nil if the file is missing; the view then keeps its space empty.
  let rive: RiveViewModel?
  /// Where the mascot is on screen, in the global coordinate space.
  var frame: CGRect = .zero
  private var pokes = MascotPokes()

  init(artboard: String = Artboard.face) {
    rive = (try? RiveModel(fileName: "axo", extension: ".riv", in: .main, loadCdn: false)).map {
      RiveViewModel($0, stateMachineName: "Mascot", fit: .contain, autoPlay: true, artboardName: artboard)
    }
  }

  /// Gills flutter and Axo bobs; on the `Loader` artboard it also spins.
  func setLoading(_ loading: Bool) {
    rive?.setInput(Input.loading, value: loading)
  }

  /// Looks towards `point` (global coordinates) while a finger is down; `screen` sets how far is
  /// far enough to look all the way.
  func look(at point: CGPoint, screen: CGSize) {
    guard let rive, frame != .zero else { return }
    let reach = CGSize(width: max(screen.width / 2, 1), height: max(screen.height / 2, 1))
    let x = (point.x - frame.midX) / reach.width * 100
    let y = (point.y - frame.midY) / reach.height * 100
    rive.setInput(Input.lookX, value: Double(min(max(x, -100), 100)))
    rive.setInput(Input.lookY, value: Double(min(max(y, -100), 100)))
    rive.setInput(Input.tracking, value: true)
  }

  func stopLooking() {
    rive?.setInput(Input.tracking, value: false)
  }

  func cover(_ covering: Bool) {
    rive?.setInput(Input.covering, value: covering)
  }

  func poke() {
    switch pokes.poke(at: Date()) {
    case .giggle: rive?.triggerInput(Input.poke)
    case .annoyed: rive?.triggerInput(Input.annoyed)
    case nil: break
    }
  }
}

/// Shows a `Mascot`. Tapping it pokes it; with Reduce Motion on it holds still.
struct AxoMascotView: View {
  /// The `Face` artboard is 1064 x 604 (`MascotBounds.face` in packages/axo-mascot).
  static let aspectRatio = 1064.0 / 604.0

  @ObservedObject var mascot: Mascot
  var aspectRatio: Double = Self.aspectRatio
  @Environment(\.accessibilityReduceMotion) private var reduceMotion

  var body: some View {
    ZStack {
      if let rive = mascot.rive {
        rive.view()
      }
    }
    .aspectRatio(aspectRatio, contentMode: .fit)
    .contentShape(Rectangle())
    .onTapGesture { mascot.poke() }
    .onGeometryChange(for: CGRect.self) { $0.frame(in: .global) } action: { mascot.frame = $0 }
    .onChange(of: reduceMotion, initial: true) { _, reduce in
      if reduce { mascot.rive?.pause() } else { mascot.rive?.play() }
    }
    .accessibilityElement()
    .accessibilityLabel("Axo")
    .accessibilityAddTraits(.isImage)
  }
}

/// A view that owns its own Axo; while `loading`, its gills flutter and it bobs.
struct OwnMascotView: View {
  var loading = false
  @StateObject private var mascot = Mascot()

  var body: some View {
    AxoMascotView(mascot: mascot)
      .onChange(of: loading, initial: true) { _, loading in mascot.setLoading(loading) }
  }
}

/// Axo spinning while something loads, in place of a spinner.
struct LoadingMascotView: View {
  var label: String
  @StateObject private var mascot = Mascot(artboard: Mascot.Artboard.loader)

  var body: some View {
    AxoMascotView(mascot: mascot, aspectRatio: 1)
      .onAppear { mascot.setLoading(true) }
      .accessibilityLabel(label)
  }
}
